description:
Data from a file or a network arrives in chunks that do not line up with lines. Write an async generator `lines(chunks)` that takes an async iterable of strings and yields complete lines:

- lines end with `\n` or `\r\n`, and the line ending is not part of the line;
- a line may be split across any number of chunks, and a chunk may hold many lines;
- text after the last line ending is yielded as a final line, but an empty final piece is not;
- a `\r\n` split between two chunks (`\r` at the end of one, `\n` at the start of the next) is one line ending.

starter.solution.js:
async function* lines(chunks) {
  for await (const chunk of chunks) yield* chunk.split("\n");
}

solution.solution.js:
async function* lines(chunks) {
  let pending = "";
  for await (const chunk of chunks) {
    pending += chunk;
    let at;
    while ((at = pending.indexOf("\n")) !== -1) {
      let line = pending.slice(0, at);
      if (line.endsWith("\r")) line = line.slice(0, -1);
      yield line;
      pending = pending.slice(at + 1);
    }
  }
  if (pending.endsWith("\r")) pending = pending.slice(0, -1);
  if (pending !== "") yield pending;
}

unitTests:
async function* from(...chunks) {
  for (const c of chunks) {
    await null;
    yield c;
  }
}
async function collect(it) {
  const out = [];
  for await (const x of it) out.push(x);
  return out;
}

test("whole lines in one chunk", async () => {
  checkEq(await collect(lines(from("a\nb\nc\n"))), ["a", "b", "c"]);
});

test("a line split across chunks", async () => {
  checkEq(await collect(lines(from("hel", "lo wo", "rld\nnext\n"))), ["hello world", "next"]);
});

test("last line without an ending", async () => {
  checkEq(await collect(lines(from("a\nb"))), ["a", "b"]);
});

test("windows line endings, even split", async () => {
  checkEq(await collect(lines(from("one\r", "\ntwo\r\n"))), ["one", "two"]);
});

test("empty lines are kept, empty end is not", async () => {
  checkEq(await collect(lines(from("a\n\nb\n"))), ["a", "", "b"]);
  checkEq(await collect(lines(from(""))), []);
});

